package vn.edu.hunre.nhom11.carrental.payment.api;import java.security.Principal;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import vn.edu.hunre.nhom11.carrental.payment.service.PaymentService;@RestController@RequestMapping("/api/payments")public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping Object pay(Principal p,Authentication a,@RequestBody PaymentService.PaymentCommand r){return service.pay(p.getName(),isAdmin(a),r);}@PostMapping("/sepay/webhook")Object sePayWebhook(@RequestHeader(value="Authorization",required=false)String authorization,@RequestBody PaymentService.SePayWebhook r){return service.receiveSePay(authorization,r);}@GetMapping("/sepay/info")@PreAuthorize("hasRole('ADMIN')")Object webhookInfo(){return service.webhookInfo();}@GetMapping @PreAuthorize("hasRole('ADMIN')") Object all(){return service.all();}@GetMapping("/{bookingId}")Object list(@PathVariable Long bookingId,Principal p,Authentication a){return service.byBooking(bookingId,p.getName(),isAdmin(a));}private boolean isAdmin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}}
